import {BottomSheet as Root} from '../bottom-sheet';
import {BottomSheet as Nested} from './bottom-sheet';
import {LonaModalWebComponent} from '../../ui/modal-component';
import {Focus} from '../../ui/focus';
export {Root,Nested};
const frame=()=>new Promise<void>(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>r())));
const sleep=(ms:number)=>new Promise<void>(r=>setTimeout(r,ms));
const check=(ok:boolean,message:string)=>{if(!ok)throw new Error(message);};
export function content():HTMLElement{const div=document.createElement('div');for(const [id,state] of [['first',''],['hidden','hidden'],['disabled','disabled'],['inert','inert'],['last','']] as const){const b=document.createElement('button');b.id=id;b.textContent=id;if(state)b.setAttribute(state,'');div.append(b);}const host=document.createElement('div');const shadow=host.attachShadow({mode:'open'});const slot=document.createElement('slot');shadow.append(slot);const action=document.createElement('button');action.id='slotted-shadow-action';action.textContent='Slotted shadow action';host.append(action);div.append(host);return div;}
export function modalProps(onDismiss:EmptyFunction):Root.Props{return {$content:content,snapPoints:[.35,.8],initialSnap:0,dismissible:true,label:'Current modal sheet',onDismiss};}
export async function verifySheetCompatibility():Promise<string[]>{
 check(Root===Nested&&customElements.get('std-bottom-sheet')===Root,'Historical/registry constructor identity');const a=Root.make(),native=document.createElement('std-bottom-sheet');let retiredSlotCalls=0;a.onDismiss=()=>retiredSlotCalls++;check(a instanceof LonaModalWebComponent&&native instanceof Root,'Native/factory/modal prototype identity');const style=document.createElement('style');style.textContent='.owned-sheet-title{color:rgb(9, 40, 80);font-weight:700}';document.head.append(style);const title=document.createElement('h2');title.slot='title';title.className='owned-sheet-title';title.textContent='Caller title';const body=document.createElement('p');body.textContent='Caller-owned slot body';a.append(title,body);document.body.append(a);check(getComputedStyle(a).display==='none','Root hidden default changed');a.open(320);await frame();check(a.isOpen&&a.$scroller.querySelector('slot')!.assignedElements().includes(body),'Root light DOM/scroller contract');check(title.getRootNode()===document&&getComputedStyle(title).color==='rgb(9, 40, 80)','Caller title stylesheet ownership');check(a.shadowRoot!.querySelector<HTMLElement>('#sheet')!.style.maxHeight==='320px','Root maximum height');a.close();a.open();await sleep(300);check(a.isOpen&&getComputedStyle(a).display!=='none','Reopen raced hide timer');a.recycle();await frame();const b=Nested.make();check(b===a,'Alias shares root class pool');let old=0,current=0;b.bind(modalProps(()=>old++));const invoker=document.createElement('button');invoker.textContent='Invoker';document.body.append(invoker);invoker.focus();b.reveal();b.bind(modalProps(()=>current++));await frame();check(old===1&&b.isOpen,'Rebinding visible modal retirement');check(b.getAttribute('role')==='dialog'&&b.getAttribute('aria-modal')==='true','Modal semantics');const close=b.shadowRoot!.querySelector('#modal-close')!.shadowRoot!.querySelector<HTMLElement>('std-icon-button')!;close.focus();check(Focus.activeDeep()===close,'Close custom host not focusable');const handle=b.shadowRoot!.querySelector<HTMLElement>('#modal-handle')!;handle.focus();handle.dispatchEvent(new KeyboardEvent('keydown',{key:'Tab',shiftKey:true,bubbles:true}));check(Focus.activeDeep()===close,'ShiftTab from handle skipped actual close target');check(Math.abs(b.shadowRoot!.querySelector<HTMLElement>('#modal-panel')!.getBoundingClientRect().height-window.innerHeight*.35)<2,'Modal initial snap');b.dismiss();b.dismiss();check(current===1,'Modal dismissal callback exactly once');await sleep(400);b.recycle();await frame();const slot=Root.make();check(slot===b,'Modal→slot actual settled pool identity');const retiredOld=old,retiredCurrent=current;let slotCalls=0;slot.append(document.createTextNode('New slot occupant'));document.body.append(slot);slot.open();check(slot.isOpen&&slot.getAttribute('presentation')==null,'Pooled mode reset');slot.dismiss();check(retiredSlotCalls===0&&old===retiredOld&&current===retiredCurrent,'Recycled callbacks must not survive slot reuse');slot.onDismiss=()=>slotCalls++;slot.open();slot.dismiss();slot.dismiss();check(slotCalls===1&&retiredSlotCalls===0&&old===retiredOld&&current===retiredCurrent,'Pooled slot dismissal must notify only its current occupant exactly once');slot.recycle();await frame();invoker.remove();style.remove();return ['Both historical entries/registry/native factory/modal prototype and shared pool identity','Root slots/title CSS/scroller/height/reopen and modal Props/snap/rebind/exact dismissal','Settled modal→slot pool mode and callback reset'];
}
export async function verifySheetFocusLifetime():Promise<string[]>{
 const invoker=document.createElement('button'),sibling=document.createElement('button');invoker.textContent='Invoker';sibling.textContent='Sibling';document.body.append(invoker,sibling);invoker.focus();let calls=0;const s=Root.show(modalProps(()=>calls++));s.dismiss();sibling.focus();await frame();check(Focus.activeDeep()===sibling&&calls===1,'Same-frame dismissal late focus/cardinality');await sleep(400);s.recycle();await frame();const next=Root.show({...modalProps(()=>calls++),$content:()=>document.createElement('p')});await frame();check(Focus.activeDeep()!=null&&Focus.isLostOrWithin(next),'Empty-content entry requires actual focus inside the live modal');next.dismiss();await sleep(400);next.recycle();await frame();const locked=Root.show({...modalProps(()=>calls++),dismissible:false,$content:()=>document.createElement('p')});await frame();check(Focus.activeDeep()!=null&&Focus.isLostOrWithin(locked),'Empty nondismissible modal requires actual focus inside its live surface');locked.dismiss();await sleep(400);locked.recycle();await frame();invoker.remove();sibling.remove();return ['Same-frame show/dismiss never steals deliberate sibling focus','No-actions modal focus remains inside live surface and dismisses once'];
}
